  // cursor
  (function(){
    const dot=document.querySelector('.cur'),ring=document.querySelector('.cur-ring');
    if(matchMedia('(hover:none)').matches)return;
    let rx=0,ry=0,x=0,y=0;
    addEventListener('mousemove',e=>{x=e.clientX;y=e.clientY;dot.style.left=x+'px';dot.style.top=y+'px';});
    (function loop(){rx+=(x-rx)*.18;ry+=(y-ry)*.18;ring.style.left=rx+'px';ring.style.top=ry+'px';requestAnimationFrame(loop);})();
    document.addEventListener('mouseover',e=>{if(e.target.closest('a,button,.fcard,.gptitem,.svc,.num,.pcard'))ring.classList.add('hot');});
    document.addEventListener('mouseout',e=>{if(e.target.closest('a,button,.fcard,.gptitem,.svc,.num,.pcard'))ring.classList.remove('hot');});
  })();

  // background sequence — SLOWER so it doesn't move too fast
  (function(){
    const seq=document.getElementById('seq'); if(!seq||!FRAMES.length)return;
    FRAMES.forEach(s=>{const i=new Image();i.src=s;});
    seq.src=FRAMES[0];
    if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;
    let i=0;setInterval(()=>{i=(i+1)%FRAMES.length;seq.src=FRAMES[i];},170);
  })();

  // coin parallax
  (function(){const c=document.getElementById('pcoin');if(!c)return;addEventListener('mousemove',e=>{const dx=(e.clientX/innerWidth-.5)*16,dy=(e.clientY/innerHeight-.5)*16;c.style.transform=`translate(${dx}px,${dy}px)`;},{passive:true});})();

  // media frame cycling
  (function(){
    const rm=matchMedia('(prefers-reduced-motion:reduce)').matches;
    document.querySelectorAll('[data-cycle]').forEach((f,idx)=>{
      const ls=[...f.querySelectorAll('.layer')]; if(ls.length<2||rm)return;
      let i=ls.findIndex(l=>l.classList.contains('on')); if(i<0){i=0;ls[0].classList.add('on');}
      setTimeout(()=>setInterval(()=>{ls[i].classList.remove('on');i=(i+1)%ls.length;ls[i].classList.add('on');},+f.dataset.cycle||1100),idx*180);
    });
  })();

  // header + overlay
  const hdr=document.getElementById('hdr');
  const os=()=>hdr.classList.toggle('scr',scrollY>40);os();addEventListener('scroll',os,{passive:true});
  const ov=document.getElementById('ov'),mb=document.getElementById('mbtn');
  const oOpen=()=>{ov.classList.add('open');document.body.style.overflow='hidden';};
  const oClose=()=>{ov.classList.remove('open');document.body.style.overflow='';};
  mb.onclick=oOpen;document.getElementById('ovx').onclick=oClose;
  ov.querySelectorAll('a').forEach(a=>a.onclick=oClose);

  // reveals
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{threshold:.12,rootMargin:'0px 0px -7% 0px'});
  document.querySelectorAll('.rev').forEach(el=>io.observe(el));

  // legal modal
  const lm=document.getElementById('lmodal');
  const showLegal=w=>{document.querySelectorAll('.ldoc').forEach(d=>d.classList.remove('show'));document.getElementById('ld-'+w).classList.add('show');lm.classList.add('open');document.body.style.overflow='hidden';lm.scrollTop=0;};
  const hideLegal=()=>{lm.classList.remove('open');document.body.style.overflow='';};
  document.querySelectorAll('.llink').forEach(b=>b.onclick=()=>showLegal(b.dataset.legal));
  document.getElementById('lclose').onclick=hideLegal;
  lm.onclick=e=>{if(e.target===lm)hideLegal();};
  addEventListener('keydown',e=>{if(e.key==='Escape'){hideLegal();oClose();}});

  // GPT suite render
  (function(){
    const wrap=document.getElementById('gptwrap');
    const total=GPTS.reduce((a,c)=>a+c.items.length,0);
    document.getElementById('gptcount').textContent=GPTS.length+' categories · '+total+' assistants';
    wrap.innerHTML=GPTS.map(cat=>`<div class="gptcat"><h3>${cat.name}</h3><div class="gptgrid">${cat.items.map(g=>`<a class="gptitem" href="${g.href}" target="_blank" rel="noopener"><span class="gn">${g.name}</span><span class="gd">${g.desc}</span><span class="ga">Open GPT</span></a>`).join('')}</div></div>`).join('');
  })();

  // playlists render
  (function(){
    const covers=['pcA','pcB','pcC','pcD','pcE','pcF'];
    const fc=document.getElementById('fcards');
    fc.innerHTML=PL.featured.map((p,i)=>`<div class="fcard"><div class="cover ${covers[i%6]}"><span class="sp">Spotify</span><span class="nm">${p.name}</span></div><div class="body"><div class="gg">${p.genre}</div><p>${p.desc}</p><div class="row"><a class="listen" href="${p.link}" target="_blank" rel="noopener">Listen</a><a class="submit" href="https://dailyplaylists.com">Submit</a></div></div></div>`).join('');
    const fmt=n=>n>=1000?(n/1000).toFixed(1)+'k':n;
    const grid=document.getElementById('plgrid');
    grid.innerHTML=PL.grid.map(p=>`<a class="plrow" href="${p.link}" target="_blank" rel="noopener"><span class="pn">${p.name}</span><span class="meta"><span class="pg">${p.genre}</span><span class="pl">${fmt(p.foll)} ▸</span></span></a>`).join('');
    document.getElementById('plcount').textContent=(PL.featured.length+PL.grid.length)+' curated playlists · live on Spotify';
  })();
